.opc/phase1/signoff.json
.opc/phase1/success.json
.opc/phase1/milestones.json
.opc/phase1/idea.json
---
[
  {
    "id": "M1",
    "artifact_required": true,
    "goal": "地基与外壳跑起来：Vite+React+TS 工程可生产构建、可启动；数据模型（Scene / Item / Placement）+ LocalStorage 持久化就位；内置素材库枚举出 3 张背景 + 14 件物件；应用外壳（报头 + 模式开关 + 场景条 + 物件抽屉 + 画布）渲染，能创建/切换场景，刷新后状态还原。",
    "criteria": [
      {
        "desc": "生产构建通过：Vite 生产构建成功、无类型错误。",
        "check": {
          "type": "command",
          "cmd": [
            "npm",
            "run",
            "build"
          ],
          "expect_exit": 0,
          "timeout_ms": 180000
        }
      },
      {
        "desc": "外壳与持久化 e2e：建场景→切场景→刷新后场景与布局状态完整还原；物件抽屉列出 14 件；场景背景不可重复且最多 3 个（建到第 4 个被阻止）。",
        "check": {
          "type": "command",
          "cmd": [
            "npx",
            "playwright",
            "test",
            "e2e/m1-shell.spec.ts",
            "--reporter=line"
          ],
          "expect_exit": 0,
          "timeout_ms": 120000
        }
      },
      {
        "desc": "外壳视觉还原「旧信」DNA：暖奶油纸底、衬线品牌/场景名、陶土红唯一强调、Workbench(报头+场景条+[抽屉|画布]) 布局，对齐 A-旧信.html 与 tokens.css。",
        "manual": true
      }
    ],
    "status": "done",
    "verdicts": [
      {
        "milestone": "M1",
        "pass": true,
        "failed": []
      }
    ]
  },
  {
    "id": "M2",
    "artifact_required": true,
    "goal": "核心变换交互顺滑：物件可从抽屉拖入画布，可拖动改位、角手柄缩放、顶部手柄旋转、移除；变换经 CSS transform；PC 与横屏手机统一用手柄；placement(x,y,scale,rotation,z) 持久化，刷新完整还原。",
    "criteria": [
      {
        "desc": "变换交互 e2e：物件从抽屉拖入→拖动改位→角手柄缩放→顶部手柄旋转→移除→刷新后 placement(x,y,scale,rotation,z) 完整还原。",
        "check": {
          "type": "command",
          "cmd": [
            "npx",
            "playwright",
            "test",
            "e2e/m2-transform.spec.ts",
            "--reporter=line"
          ],
          "expect_exit": 0,
          "timeout_ms": 120000
        }
      },
      {
        "desc": "顺滑手感：拖/缩/转跟手、无肉眼可见掉帧或位置/角度跳变、手柄命中准；在 PC 与横屏手机各验一遍。",
        "manual": true
      },
      {
        "desc": "变换仅走 transform/opacity、不触发布局重排（合成层 + requestAnimationFrame 提交）。",
        "manual": true
      }
    ],
    "status": "done",
    "verdicts": [
      {
        "milestone": "M2",
        "pass": true,
        "failed": []
      }
    ]
  },
  {
    "id": "M3",
    "artifact_required": true,
    "goal": "物件故事与编辑/游客双模式：选中物件写/改故事（故事挂物件本身、跨场景同步）；点物件弹出半透明故事弹窗（含原始图片）；编辑↔游客一键切换；游客模式只读，点物件只弹故事+原图、不能编辑；故事持久化。",
    "criteria": [
      {
        "desc": "故事与双模式 e2e：选中物件写故事→刷新后还原→同一物件在另一场景故事同步更新→切游客模式点物件只弹故事+原图且不可编辑/移动。",
        "check": {
          "type": "command",
          "cmd": [
            "npx",
            "playwright",
            "test",
            "e2e/m3-story.spec.ts",
            "--reporter=line"
          ],
          "expect_exit": 0,
          "timeout_ms": 120000
        }
      },
      {
        "desc": "故事弹窗视觉：半透明奶油底 + backdrop-blur 透出背后画布、陶土红衬线、含原始照片，浮于画布之上不占画布宽度，还原「旧信」DNA。",
        "manual": true
      }
    ],
    "claimed_at_tick": 8
  },
  {
    "id": "M4",
    "artifact_required": true,
    "goal": "收口·全流程 + 双端达标：覆盖 6 条成功条件的端到端全流程在 PC 与横屏手机都跑通、布局不错乱；整体还原「旧信」DNA；无横向溢出、无未捕获运行时错误。",
    "criteria": [
      {
        "desc": "全流程 + 双端 e2e：覆盖 6 条成功条件主链路，在 PC / 768px / 375px 三视口跑通；无横向溢出；无 console 未捕获错误或未处理的 Promise 拒绝。",
        "check": {
          "type": "command",
          "cmd": [
            "npx",
            "playwright",
            "test",
            "e2e/m4-full.spec.ts",
            "--reporter=line"
          ],
          "expect_exit": 0,
          "timeout_ms": 180000
        }
      },
      {
        "desc": "双端布局与整体视觉验收：横屏手机布局不错乱、元素不溢出遮挡；整体还原「旧信」DNA（配色/字体/间距/弹窗/手柄均走 tokens.css）。",
        "manual": true
      }
    ]
  }
]

